def human_size(n: float) -> str:
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n:.0f} {unit}" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024
    return ""


# ───────────────────────────── Crypto / storage ──────────────────────────
b64 = lambda b: base64.b64encode(b).decode()
unb64 = lambda s: base64.b64decode(s)


class Vault:
    CH = 4 * 1024 * 1024

    def __init__(self, root: Path) -> None:
        self.root = root                    # one folder per user
        self.root.mkdir(parents=True, exist_ok=True)
        self.blobs, self.meta = self.root / "blobs", self.root / "vault.meta"
        self.index_path = self.root / "index.vlt"
        self.tmp = self.root / "open"
        self.key: bytes | None = None
        self.entries: list[dict] = []
        self.folders: list[str] = []

    # --- key handling
    def exists(self) -> bool:
        return self.meta.exists()

    @staticmethod
    def _derive(pw: str, salt: bytes, n: int = LEGACY_N) -> bytes:
        return Scrypt(salt=salt, length=32, n=n, r=8, p=1).derive(pw.encode())

    @staticmethod
    def _seal(key: bytes, data: bytes) -> bytes:
        nonce = os.urandom(12)
        return nonce + AESGCM(key).encrypt(nonce, data, None)

    @staticmethod
    def _open(key: bytes, blob: bytes) -> bytes:
        return AESGCM(key).decrypt(blob[:12], blob[12:], None)

    # --- keys: a random master key, wrapped separately by the password and the backup password
    def _meta(self) -> dict:
        try:
            return json.loads(self.meta.read_text())
        except (OSError, ValueError):                       # damaged: fall back to the last good copy
            return json.loads(self.meta.with_suffix(".bak").read_text())

    def _write_meta(self, m: dict) -> None:
        tmp = self.meta.with_suffix(".tmp")
        tmp.write_text(json.dumps(m))
        if self.meta.exists():
            shutil.copy2(self.meta, self.meta.with_suffix(".bak"))
        os.replace(tmp, self.meta)                          # atomic: never a half-written file

    def _wrap(self, pw: str) -> dict:
        salt = os.urandom(16)
        return {"salt": b64(salt), "n": KDF_N, "wrap": b64(self._seal(self._derive(pw, salt, KDF_N), self.key))}

    @staticmethod
    def _try(pw: str, slot: dict | None):
        if not slot:
            return None
        try:
            return Vault._open(Vault._derive(pw, unb64(slot["salt"]), slot.get("n", LEGACY_N)), unb64(slot["wrap"]))
        except InvalidTag:
            return None

    def title(self) -> str:
        try:
            return self._meta().get("title") or APP_NAME     # stored in plain text so the lock screen can show it
        except Exception:
            return APP_NAME

    def set_title(self, t: str) -> None:
        m = self._meta(); m["title"] = t.strip() or APP_NAME; self._write_meta(m)

    def create(self, pw: str, title: str = APP_NAME) -> None:
        self.blobs.mkdir(parents=True, exist_ok=True)
        self.key, self.entries, self.folders = os.urandom(32), [], []
        self._write_meta({"v": 2, "title": title, "main": self._wrap(pw)})
        self._save()

    def unlock(self, pw: str) -> bool:
        m = self._meta()
        hit = key = None
        if "main" in m:
            for name in ("main", "backup"):
                key = self._try(pw, m.get(name))
                if key: hit = name; break   # password OR backup password
        else:                                   # legacy vault: key was derived straight from the password
            try:
                key = self._derive(pw, unb64(m["salt"])); self._open(key, unb64(m["check"]))
            except InvalidTag:
                key = None
        if key is None:
            return False
        raw = self._load_index(key)
        self.key = key
        if isinstance(raw, list):
            raw = {"entries": raw}
        self.entries, self.folders = raw.get("entries", []), raw.get("folders", [])
        if "main" not in m:                     # upgrade legacy vault in place (files stay readable)
            shutil.copy2(self.meta, self.meta.with_suffix(".legacy"))        # keep the pre-upgrade meta file
            self._write_meta({"v": 2, "title": m.get("title", APP_NAME), "main": self._wrap(pw)})
        elif hit and m[hit].get("n", LEGACY_N) < KDF_N:                       # re-wrap at the current scrypt cost
            m[hit] = self._wrap(pw); self._write_meta(m)
        return True

    def lock(self) -> None:
        self.key, self.entries, self.folders = None, [], []

    def _save(self) -> None:
        tmp = self.index_path.with_suffix(".tmp")
        tmp.write_bytes(self._seal(self.key, json.dumps({"entries": self.entries, "folders": self.folders}).encode()))
        if self.index_path.exists():
            shutil.copy2(self.index_path, self.index_path.with_suffix(".bak"))   # rolling copy of the last good index
        os.replace(tmp, self.index_path)

    def change_password(self, pw: str) -> None:
        m = self._meta()
        if self._try(pw, m.get("backup")):
            raise ValueError("Your main and backup passwords must be different.")
        m["main"] = self._wrap(pw); self._write_meta(m)

    def has_backup(self) -> bool:
        return "backup" in self._meta()

    def set_backup(self, pw: str) -> None:
        m = self._meta()
        if self._try(pw, m["main"]):
            raise ValueError("Your backup password must be different from your main password.")
        m["backup"] = self._wrap(pw); self._write_meta(m)

    def remove_backup(self) -> None:
        m = self._meta(); m.pop("backup", None); self._write_meta(m)

    def _load_index(self, key: bytes) -> dict:
        existing = [q for q in (self.index_path, self.index_path.with_suffix(".bak")) if q.exists()]
        for q in existing:
            try:
                return json.loads(self._open(key, q.read_bytes()))
            except (ValueError, InvalidTag):
                continue
        if existing:                                        # never silently start empty: that would orphan every file
            raise ValueError("The vault index is damaged and no readable backup copy exists.")
        return {}

    def backup(self, dest: str, cb) -> str:
        """Zip the already-encrypted vault files. Safe to store anywhere; useless without a password."""
        files = [self.meta, self.index_path] + sorted(self.blobs.glob("*.vlt"))
        with zipfile.ZipFile(dest, "w", zipfile.ZIP_STORED) as z:
            for i, f in enumerate(files):
                z.write(f, f.relative_to(self.root).as_posix()); cb((i + 1) / len(files))
        return dest

    # --- folders
    @staticmethod
    def _clean(name: str) -> str:
        return name.strip().replace("/", " ").replace("\\", " ").strip()

    def add_folder(self, parent: str, name: str) -> None:
        n = self._clean(name)
        if not n: raise ValueError("Enter a folder name.")
        path = f"{parent}/{n}" if parent else n
        if path in self.folders: raise ValueError("A folder with that name already exists.")
        self.folders.append(path); self._save()

    def rename_folder(self, path: str, name: str) -> None:
        n = self._clean(name)
        if not n: raise ValueError("Enter a folder name.")
        parent = path.rpartition("/")[0]
        new = f"{parent}/{n}" if parent else n
        if new != path and new in self.folders: raise ValueError("A folder with that name already exists.")
        remap = lambda f: new + f[len(path):] if f == path or f.startswith(path + "/") else f
        self.folders = [remap(f) for f in self.folders]
        for e in self.entries: e["folder"] = remap(e.get("folder", ""))
        self._save()

    def delete_folder(self, path: str) -> None:
        inside = lambda f: f == path or f.startswith(path + "/")
        if any(inside(e.get("folder", "")) for e in self.entries) or any(f.startswith(path + "/") for f in self.folders):
            raise ValueError("This folder isn't empty. Move or delete what's inside first.")
        self.folders.remove(path); self._save()

    def move(self, entry: dict, folder: str) -> None:
        entry["folder"] = folder; self._save()

    # --- file operations (run inside a worker thread)
    @staticmethod
    def _aad(entry: dict, last: bool) -> bytes:
        """fmt 2 binds every chunk to its entry id (a swapped blob fails authentication); legacy blobs used only the flag."""
        return (entry["id"].encode() if entry.get("fmt") == 2 else b"") + (b"\x01" if last else b"\x00")

    def _file_chunks(self, path: str):
        with open(path, "rb") as f:
            while chunk := f.read(self.CH):
                yield chunk

    def _write_blob(self, chunks, entry: dict, blob: Path, on_bytes) -> None:
        """Encrypt an iterable of plaintext chunks into `blob` in the fmt-2 layout."""
        aes, new_fmt = AESGCM(self.key), {"id": entry["id"], "fmt": 2}
        with open(blob, "wb") as dst:
            base, i = os.urandom(8), 0
            dst.write(base)
            it = iter(chunks); cur = next(it, b"")
            while True:
                nxt = next(it, None); last = nxt is None
                dst.write(aes.encrypt(base + i.to_bytes(4, "big"), cur, self._aad(new_fmt, last)))
                on_bytes(len(cur))
                if last:
                    break
                cur, i = nxt, i + 1

    def _open_chunks(self, entry: dict):
        """Yield authenticated plaintext chunks (raises InvalidTag on any tampering, truncation or swap)."""
        aes = AESGCM(self.key)
        with open(self.blobs / f"{entry['id']}.vlt", "rb") as src:
            base, i = src.read(8), 0
            cur = src.read(self.CH + 16)
            while True:
                nxt = src.read(self.CH + 16); last = not nxt
                yield aes.decrypt(base + i.to_bytes(4, "big"), cur, self._aad(entry, last))
                if last:
                    break
                cur, i = nxt, i + 1

    def _decrypt_stream(self, entry: dict, write, cb) -> None:
        done = 0
        for data in self._open_chunks(entry):
            write(data); done += len(data); cb(done / max(1, entry["size"]))

    def verify(self, cb) -> dict:
        """Authenticate every file without writing plaintext anywhere; report damaged, missing and unreferenced blobs."""
        res = {"checked": 0, "damaged": [], "missing": [], "orphans": []}
        for i, e in enumerate(self.entries):
            if not (self.blobs / f"{e['id']}.vlt").exists():
                res["missing"].append(e["name"])
            else:
                try:
                    if sum(len(c) for c in self._open_chunks(e)) != e["size"]:
                        res["damaged"].append(e["name"])
                except (InvalidTag, OSError, ValueError):
                    res["damaged"].append(e["name"])
            res["checked"] += 1; cb((i + 1) / max(1, len(self.entries)))
        known = {e["id"] for e in self.entries}
        res["orphans"] = [f.name for f in self.blobs.glob("*.vlt") if f.stem not in known]
        return res

    def upgrade_blobs(self, cb) -> int:
        """Re-encrypt legacy files into fmt 2, chunk by chunk (no plaintext is written to disk)."""
        todo = [e for e in self.entries if e.get("fmt") != 2]
        for i, e in enumerate(todo):
            blob = self.blobs / f"{e['id']}.vlt"; new = blob.with_suffix(".new")
            self._write_blob(self._open_chunks(e), e, new, lambda n: None)
            os.replace(new, blob); e["fmt"] = 2; self._save()
            cb((i + 1) / len(todo))
        return len(todo)

    def _ensure_folder(self, path: str) -> None:
        parts = path.split("/")
        for i in range(1, len(parts) + 1):
            f = "/".join(parts[:i])
            if f not in self.folders:
                self.folders.append(f)

    def plan(self, paths: list[str], folder: str) -> list[tuple[str, str]]:
        """Expand dropped files/folders into [(file, vault_folder)], recreating each folder tree inside `folder`."""
        items: list[tuple[str, str]] = []
        for p in paths:
            if os.path.isdir(p):
                root = Path(p)
                base = f"{folder}/{root.name}" if folder else root.name
                for dirpath, _, files in os.walk(p):
                    rel = Path(dirpath).relative_to(root).as_posix()
                    vf = base if rel == "." else f"{base}/{rel}"
                    self._ensure_folder(vf)                     # empty folders are kept too
                    items += [(os.path.join(dirpath, f), vf) for f in files]
            elif os.path.isfile(p):
                items.append((p, folder))
        self._save()
        return items

    def add_files(self, paths: list[str], folder: str, delete_originals: bool, cb) -> list[dict]:
        """Vault files and whole folders. Unreadable/locked files are skipped (listed in self.skipped)."""
        self.skipped: list[str] = []
        items = self.plan(paths, folder)
        total = max(1, sum(os.path.getsize(p) for p, _ in items))
        done, added, vaulted = 0, [], []
        for p, vf in items:
            try:
                st = os.stat(p)
            except OSError:
                self.skipped.append(p); continue
            entry = {"id": uuid.uuid4().hex, "fmt": 2, "folder": vf, "name": os.path.basename(p), "size": st.st_size,
                     "mime": mimetypes.guess_type(p)[0] or "application/octet-stream", "mtime": st.st_mtime}

            def on_bytes(n: int) -> None:
                nonlocal done
                done += n
                cb(done / total)

            try:
                self._write_blob(self._file_chunks(p), entry, self.blobs / f"{entry['id']}.vlt", on_bytes)
            except OSError:
                (self.blobs / f"{entry['id']}.vlt").unlink(missing_ok=True)
                self.skipped.append(p); continue
            self.entries.append(entry); added.append(entry); vaulted.append(p)
            if len(added) % 25 == 0:
                self._save()                                    # batch index writes for big folders
        self._save()
        if delete_originals:                                    # only once the index is safely written
            for p in vaulted:
                try:
                    os.remove(p)
                except OSError:
                    pass
            for p in paths:                                     # then clear out the emptied source folders
                if os.path.isdir(p):
                    for dp, _, _ in os.walk(p, topdown=False):
                        try:
                            os.rmdir(dp)
                        except OSError:
                            pass
        return added

    def export(self, entry: dict, dest_dir: str, cb) -> str:
        out = Path(dest_dir) / entry["name"]
        n = 1
        while out.exists():
            out = out.with_name(f"{Path(entry['name']).stem} ({n}){Path(entry['name']).suffix}")
            n += 1
        with open(out, "wb") as dst:
            self._decrypt_stream(entry, dst.write, cb)
        return str(out)

    def read_bytes(self, entry: dict, cb) -> bytes:
        """Decrypt fully in memory (used for the built-in image viewer; nothing touches disk)."""
        buf = bytearray()
        self._decrypt_stream(entry, buf.extend, cb)
        return bytes(buf)

    def open_temp(self, entry: dict, cb) -> str:
        """Decrypt into a private temp folder so the file can open in its normal app."""
        d = self.tmp / entry["id"]
        d.mkdir(parents=True, exist_ok=True)
        out = d / entry["name"]
        with open(out, "wb") as dst:
            self._decrypt_stream(entry, dst.write, cb)
        return str(out)

    def replace_blob(self, entry: dict, path: str) -> None:
        """Re-encrypt an edited temp copy back into the vault."""
        blob = self.blobs / f"{entry['id']}.vlt"
        new = blob.with_suffix(".new")
        self._write_blob(self._file_chunks(path), entry, new, lambda n: None)
        os.replace(new, blob)
        entry["fmt"] = 2
        st = os.stat(path)
        entry["size"], entry["mtime"] = st.st_size, st.st_mtime
        self._save()

    @staticmethod
    def wipe_file(path: Path) -> None:
        """Best-effort overwrite with zeros (not guaranteed on SSDs)."""
        size = os.path.getsize(path)
        with open(path, "r+b") as f:
            for _ in range(0, size, 1 << 20):
                f.write(b"\0" * min(1 << 20, size))
            f.flush()

    def wipe_tmp(self) -> None:
        shutil.rmtree(self.tmp, ignore_errors=True)

    def remove(self, entry: dict) -> None:
        (self.blobs / f"{entry['id']}.vlt").unlink(missing_ok=True)
        self.entries = [e for e in self.entries if e["id"] != entry["id"]]
        self._save()


class UserStore:
    """Plain-text list of profiles (name, avatar, colour). Each user's files live in users/<id>/ under their own password."""
    def __init__(self) -> None:
        base = Path(os.environ.get("APPDATA", Path.home()))
        old = base / "LimewashVault"
        self.root = base / "DaedalusVault"
        if old.exists() and not self.root.exists():
            old.rename(self.root)
        self.root.mkdir(parents=True, exist_ok=True)
        self.file = self.root / "users.json"
        self.users: list[dict] = json.loads(self.file.read_text()) if self.file.exists() else []
        if not self.users and (self.root / "vault.meta").exists():       # adopt the single-user vault from older versions
            u = self.add("Me")
            for n in ("vault.meta", "index.vlt", "blobs"):
                if (self.root / n).exists():
                    shutil.move(str(self.root / n), str(self.dir(u["id"]) / n))
            shutil.rmtree(self.root / "open", ignore_errors=True)

    def dir(self, uid: str) -> Path:
        return self.root / "users" / uid

    def save(self) -> None:
        self.file.write_text(json.dumps(self.users))

    def add(self, name: str) -> dict:
        u = {"id": uuid.uuid4().hex[:10], "name": name, "color": PALETTE[len(self.users) % len(PALETTE)], "avatar": ""}
        self.users.append(u); self.dir(u["id"]).mkdir(parents=True, exist_ok=True); self.save()
        return u

    def update(self, u: dict, **kw) -> None:
        u.update(kw); self.save()

    def remove(self, u: dict) -> None:
        shutil.rmtree(self.dir(u["id"]), ignore_errors=True); self.users.remove(u); self.save()

    def avatar_path(self, u: dict):
        if not u.get("avatar"): return None
        p = self.dir(u["id"]) / u["avatar"]
        return p if p.exists() else None

    def set_avatar(self, u: dict, src: str) -> None:
        img = QImage(src)
        if img.isNull(): raise ValueError("Couldn't read that image.")
        side = min(img.width(), img.height())          # centre-crop to a square, then shrink
        img = img.copy((img.width() - side) // 2, (img.height() - side) // 2, side, side).scaled(256, 256, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        img.save(str(self.dir(u["id"]) / "avatar.png"), "PNG")
        self.update(u, avatar="avatar.png")

    def clear_avatar(self, u: dict) -> None:
        (self.dir(u["id"]) / "avatar.png").unlink(missing_ok=True); self.update(u, avatar="")

    def restore(self, src: str, name: str) -> dict:
        """Create a new user from a backup. Only vault files are accepted (blocks path-traversal entries)."""
        ok = re.compile(r"^(vault\.meta|index\.vlt|blobs/[0-9a-f]{32}\.vlt)$")
        try:
            with zipfile.ZipFile(src) as z:
                names = z.namelist()
                if "vault.meta" not in names or not all(ok.match(n) for n in names):
                    raise ValueError("That isn't a valid Daedalus backup.")
                u = self.add(name)
                try:
                    z.extractall(self.dir(u["id"]))
                except Exception:
                    self.remove(u); raise
        except zipfile.BadZipFile as e:
            raise ValueError("That isn't a valid Daedalus backup.") from e
        return u

    def wipe_all_tmp(self) -> None:
        for u in self.users: shutil.rmtree(self.dir(u["id"]) / "open", ignore_errors=True)


class Job(QThread):
    """Runs a Vault operation off the UI thread so animations stay smooth."""
    progress, ok, fail = Signal(float), Signal(object), Signal(str)

    def __init__(self, fn) -> None:
        super().__init__()
        self.fn = fn

    def run(self) -> None:
        try:
            self.ok.emit(self.fn(self.progress.emit))
        except Exception as e:  # noqa: BLE001
            self.fail.emit(str(e))


