# ───────────────────────────── Vault view ────────────────────────────────
class VaultView(QWidget):
    lockRequested = Signal()
    addRequested = Signal(list)
    openRequested, moveRequested, exportRequested, deleteRequested = Signal(dict), Signal(dict), Signal(dict), Signal(dict)
    newFolderRequested, settingsRequested = Signal(), Signal()
    renameFolder, deleteFolder = Signal(str), Signal(str)

    def __init__(self) -> None:
        super().__init__()
        self.cards: list[QWidget] = []
        self._entries, self._folders, self.cur = [], [], ""
        root = QVBoxLayout(self); root.setContentsMargins(36, 28, 36, 28); root.setSpacing(18)

        head = QHBoxLayout()
        col = QVBoxLayout(); col.setSpacing(2)
        self.title_lbl = t = QLabel("Your Vault"); t.setFont(spaced(16, 4))
        self.count = QLabel(); self.count.setStyleSheet(f"color:{MUTED}; font:10pt '{FONT}';")
        col.addWidget(t); col.addWidget(self.count)
        lock = QPushButton("Lock vault"); lock.setObjectName("primary"); lock.setCursor(Qt.PointingHandCursor)
        lock.clicked.connect(self.lockRequested)
        head.addWidget(logo_label(52)); head.addSpacing(6); head.addLayout(col); head.addStretch()
        nf, st = QPushButton("New folder"), QPushButton("Settings")
        nf.clicked.connect(self.newFolderRequested); st.clicked.connect(self.settingsRequested)
        self.avatar = Avatar(40); head.addSpacing(4); head.addWidget(self.avatar); head.addSpacing(6)
        for b in (nf, st, lock): b.setCursor(Qt.PointingHandCursor); head.addWidget(b)
        root.addLayout(head)
        nav = QHBoxLayout()
        self.back = QPushButton("←  Back"); self.back.setCursor(Qt.PointingHandCursor)
        self.back.clicked.connect(lambda: self.go(self.cur.rpartition("/")[0]))
        self.crumb = QLabel(); self.crumb.setStyleSheet(f"color:{MUTED}; font:10pt '{FONT}';")
        nav.addWidget(self.back); nav.addWidget(self.crumb); nav.addStretch(); root.addLayout(nav)

        self.zone = DropZone()
        self.zone.filesDropped.connect(self.addRequested)
        self.zone.clicked.connect(self._browse)
        root.addWidget(self.zone)
        self.delete_orig = QCheckBox("Remove original files after sealing"); self.delete_orig.setChecked(True)
        opts = QHBoxLayout(); opts.addWidget(self.delete_orig); opts.addStretch()
        af = QPushButton("Add folder…"); af.setCursor(Qt.PointingHandCursor); af.clicked.connect(self._browse_folder)
        opts.addWidget(af); root.addLayout(opts)

        self.scroll = QScrollArea(); self.scroll.setWidgetResizable(True); self.scroll.setFrameShape(QFrame.NoFrame)
        holder = QWidget(); self.grid = QGridLayout(holder)
        self.grid.setSpacing(16); self.grid.setContentsMargins(4, 4, 4, 16); self.grid.setAlignment(Qt.AlignTop | Qt.AlignLeft)
        self.scroll.setWidget(holder)
        root.addWidget(self.scroll, 1)

    def _browse_folder(self) -> None:
        if self.zone.busy: return
        d = QFileDialog.getExistingDirectory(self, "Choose a folder to vault")
        if d: self.addRequested.emit([d])

    def _browse(self) -> None:
        if self.zone.busy: return
        paths, _ = QFileDialog.getOpenFileNames(self, "Choose files to vault")
        if paths: self.addRequested.emit(paths)

    def refresh(self, entries: list[dict], folders: list[str]) -> None:
        self._entries, self._folders = entries, folders
        if self.cur and self.cur not in folders: self.cur = ""
        self._render()

    def go(self, path: str) -> None:
        self.cur = path; self._render()

    def _render(self) -> None:
        for c in self.cards:
            c.setParent(None); c.deleteLater()
        self.cards, cur = [], self.cur
        for f in sorted((f for f in self._folders if f.rpartition("/")[0] == cur), key=str.lower):
            n = sum(e.get("folder", "") == f for e in self._entries) + sum(g.rpartition("/")[0] == f for g in self._folders)
            c = FolderCard(f, n)
            c.opened.connect(self.go); c.renameClicked.connect(self.renameFolder); c.deleteClicked.connect(self.deleteFolder)
            self.cards.append(c)
        for e in sorted((e for e in self._entries if e.get("folder", "") == cur), key=lambda x: x["name"].lower()):
            c = FileCard(e)
            c.openClicked.connect(self.openRequested); c.moveClicked.connect(self.moveRequested)
            c.exportClicked.connect(self.exportRequested); c.deleteClicked.connect(self.deleteRequested)
            self.cards.append(c)
        n = len(self._entries)
        self.count.setText(f"{n} file{'s' if n != 1 else ''} sealed" if n else "Nothing sealed yet")
        self.back.setVisible(bool(cur))
        self.crumb.setText("  ›  ".join(["Vault"] + cur.split("/")) if cur else "Vault")
        self._reflow()

    def _reflow(self) -> None:
        while self.grid.count(): self.grid.takeAt(0)
        cols = max(1, (self.scroll.viewport().width() - 8) // (FileCard.CARD_W + 16))
        for i, c in enumerate(self.cards):
            self.grid.addWidget(c, i // cols, i % cols)

    def resizeEvent(self, e) -> None:
        super().resizeEvent(e); self._reflow()


# ───────────────────────────── Password dialog ───────────────────────────
class PasswordDialog(QDialog):
    def __init__(self, parent, create: bool, submit, title=None, sub=None, ok_text=None) -> None:
        super().__init__(parent)
        self.create, self.submit = create, submit
        self.setWindowTitle(title or ("Create your vault" if create else "Unlock vault"))
        self.setFixedWidth(390)
        lay = QVBoxLayout(self); lay.setContentsMargins(30, 28, 30, 24); lay.setSpacing(12)
        t = QLabel(self.windowTitle()); t.setFont(QFont(FONT, 15, QFont.DemiBold))
        s = QLabel(sub or ("Choose a strong password. Add a backup password later in Settings in case you forget it." if create else "Enter your password or your backup password."))
        s.setWordWrap(True); s.setStyleSheet(f"color:{MUTED}; font:10pt '{FONT}';")
        self.pw, self.pw2 = QLineEdit(), QLineEdit()
        self.pw.setPlaceholderText("Password"); self.pw2.setPlaceholderText("Confirm password")
        for f in (self.pw, self.pw2):
            f.setEchoMode(QLineEdit.Password); f.returnPressed.connect(self._go)
        self.err = QLabel(""); self.err.setStyleSheet(f"color:{ERROR}; font:9pt '{FONT}';")
        btns = QHBoxLayout(); btns.addStretch()
        cancel, ok = QPushButton("Cancel"), QPushButton(ok_text or ("Create" if create else "Unlock"))
        ok.setObjectName("primary"); ok.setDefault(True)
        cancel.clicked.connect(self.reject); ok.clicked.connect(self._go)
        btns.addWidget(cancel); btns.addWidget(ok)
        for w in (t, s, self.pw): lay.addWidget(w)
        if create: lay.addWidget(self.pw2)
        lay.addWidget(self.err); lay.addLayout(btns)

    def _go(self) -> None:
        pw = self.pw.text()
        if self.create:
            if len(pw) < 8: return self._fail("Use at least 8 characters.")
            if pw != self.pw2.text(): return self._fail("Passwords don't match.")
        elif not pw:
            return
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            error = self.submit(pw)
        finally:
            QApplication.restoreOverrideCursor()
        self._fail(error) if error else self.accept()

    def _fail(self, msg: str) -> None:
        self.err.setText(msg); self.pw.clear(); self.pw2.clear(); self.pw.setFocus()
        a = QPropertyAnimation(self, b"pos", self); x, y = self.x(), self.y()   # tactile shake
        a.setDuration(320)
        for t, dx in ((0, 0), (.2, -9), (.4, 9), (.6, -6), (.8, 5), (1, 0)): a.setKeyValueAt(t, QPoint(x + dx, y))
        a.start(QPropertyAnimation.DeleteWhenStopped)


# ───────────────────────────── Main window ───────────────────────────────
class Avatar(QWidget):
    """Round avatar with a ring in the user's colour; falls back to initials."""
    def __init__(self, size: int) -> None:
        super().__init__(); self.setFixedSize(size, size); self.setAttribute(Qt.WA_TransparentForMouseEvents)
        self.pm, self.name, self.color = None, "?", ACCENT

    def set_user(self, user: dict, store: UserStore) -> None:
        self.name, self.color = user["name"], user.get("color", ACCENT)
        path = store.avatar_path(user)
        pm = QPixmap(str(path)) if path else None
        self.pm = pm if pm is not None and not pm.isNull() else None
        self.update()

    def paintEvent(self, _) -> None:
        p = QPainter(self); p.setRenderHints(QPainter.Antialiasing | QPainter.SmoothPixmapTransform)
        r = QRectF(self.rect()).adjusted(4, 4, -4, -4)
        if self.pm:
            clip = QPainterPath(); clip.addEllipse(r); p.setClipPath(clip); p.drawPixmap(r.toRect(), self.pm); p.setClipping(False)
        else:
            p.setPen(Qt.NoPen); p.setBrush(QColor(SURFACE_HI)); p.drawEllipse(r)
            p.setPen(QColor(INK)); p.setFont(spaced(max(8, int(self.width() * 0.3)), 0))
            p.drawText(r, Qt.AlignCenter, "".join(w[0] for w in self.name.split()[:2]).upper() or "?")
        p.setPen(QPen(QColor(self.color), 2.5)); p.setBrush(Qt.NoBrush); p.drawEllipse(r.adjusted(-2, -2, 2, 2))


class UserCard(TactileCard):
    def __init__(self, user: dict, store: UserStore, label: str | None = None) -> None:
        super().__init__()
        self.setCursor(Qt.PointingHandCursor); self.setFixedSize(190, 210)
        lay = QVBoxLayout(self); lay.setContentsMargins(24, 30, 24, 24); lay.setSpacing(10)
        av = Avatar(92); av.set_user(user, store); lay.addWidget(av, 0, Qt.AlignCenter)
        n = QLabel(label or user["name"]); n.setFont(spaced(11, 1)); n.setAlignment(Qt.AlignCenter)
        n.setAttribute(Qt.WA_TransparentForMouseEvents); lay.addWidget(n)

    def enterEvent(self, _) -> None: self.set_state("hover")
    def leaveEvent(self, _) -> None: self.set_state("rest")


class UserPicker(QWidget):
    chosen, addRequested, restoreRequested = Signal(dict), Signal(), Signal()

    def __init__(self) -> None:
        super().__init__()
        lay = QVBoxLayout(self); lay.setContentsMargins(40, 28, 40, 12); lay.setSpacing(10)
        lay.addWidget(logo_label(84), 0, Qt.AlignCenter)
        t = QLabel("WHO’S ENTERING?"); t.setFont(spaced(16, 5)); t.setAlignment(Qt.AlignCenter); lay.addWidget(t)
        s = QLabel("Every user has their own private vault and password"); s.setAlignment(Qt.AlignCenter)
        s.setStyleSheet(f"color:{MUTED}; font:10pt '{FONT}';"); lay.addWidget(s)
        sc = QScrollArea(); sc.setWidgetResizable(True); sc.setFrameShape(QFrame.NoFrame)
        holder = QWidget(); self.grid = QGridLayout(holder); self.grid.setSpacing(22); self.grid.setAlignment(Qt.AlignTop | Qt.AlignHCenter)
        sc.setWidget(holder); lay.addWidget(sc, 1)
        rb = QPushButton("Restore from backup…"); rb.setCursor(Qt.PointingHandCursor); rb.clicked.connect(self.restoreRequested)
        lay.addWidget(rb, 0, Qt.AlignCenter)

    def refresh(self, store: UserStore) -> None:
        while self.grid.count():
            w = self.grid.takeAt(0).widget()
            if w: w.setParent(None); w.deleteLater()
        cards = []
        for u in store.users:
            c = UserCard(u, store); c.clicked.connect(lambda u=u: self.chosen.emit(u)); cards.append(c)
        add = UserCard({"name": "+", "color": MUTED}, store, "Add user"); add.clicked.connect(self.addRequested); cards.append(add)
        for i, c in enumerate(cards): self.grid.addWidget(c, i // 3, i % 3)


class ImageViewer(QDialog):
    """Built-in viewer: the image is decoded from memory, never written to disk."""
    def __init__(self, parent, name: str, data: bytes) -> None:
        super().__init__(parent)
        self.setWindowTitle(name); self.resize(980, 740)
        self.pix = QPixmap(); self.pix.loadFromData(data)
        self.lbl = QLabel(alignment=Qt.AlignCenter)
        self.lbl.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Ignored)
        self.lbl.setStyleSheet(f"background:{SURFACE}; border:1px solid {LINE}; border-radius:{RADIUS}px;")
        lay = QVBoxLayout(self); lay.setContentsMargins(18, 18, 18, 18); lay.addWidget(self.lbl)

    def valid(self) -> bool:
        return not self.pix.isNull()

    def _fit(self) -> None:
        if self.valid():
            self.lbl.setPixmap(self.pix.scaled(self.lbl.size() * 0.96, Qt.KeepAspectRatio, Qt.SmoothTransformation))

    def resizeEvent(self, e) -> None:
        super().resizeEvent(e); self._fit()

    def showEvent(self, e) -> None:
        super().showEvent(e); self._fit()


class MainWindow(QMainWindow):
    def __init__(self) -> None:
        super().__init__()
        self.setWindowIcon(QIcon(logo_pixmap()))
        self.resize(980, 800); self.setMinimumSize(820, 640)
        self.store, self._job = UserStore(), None
        self.vault, self.user = None, None          # chosen on the profile screen
        self.store.wipe_all_tmp()          # remove any decrypted leftovers from a crashed session
        self.opened: dict[str, dict] = {}   # entry id -> {entry, path, stamp, wiped}
        self.stack = QStackedWidget()
        shell = Backdrop(); sl = QVBoxLayout(shell); sl.setContentsMargins(0, 0, 0, 0); sl.setSpacing(0)
        sl.addWidget(self.stack, 1)
        footer = QLabel(f"Created by {AUTHOR}"); footer.setAlignment(Qt.AlignCenter)   # very bottom of the app
        footer.setStyleSheet(f"color:{MUTED}; font:9pt '{FONT}'; padding:10px 0 14px 0;")
        sl.addWidget(footer)
        self.setCentralWidget(shell)

        self.locked_page = QWidget(); lp = QVBoxLayout(self.locked_page)
        lp.setContentsMargins(40, 24, 40, 12); lp.setAlignment(Qt.AlignCenter); lp.setSpacing(10)
        lp.addWidget(logo_label(84), 0, Qt.AlignCenter)
        self.brand = brand = QLabel(""); brand.setFont(spaced(18, 6)); brand.setAlignment(Qt.AlignCenter)
        lp.addWidget(brand)
        chip = QHBoxLayout(); chip.setSpacing(10); chip.addStretch()
        self.chip_av = Avatar(36); self.chip_name = QLabel(); self.chip_name.setFont(spaced(10, 1))
        sw = QPushButton("Switch user"); sw.setCursor(Qt.PointingHandCursor); sw.clicked.connect(lambda: self._show_picker())
        for w in (self.chip_av, self.chip_name, sw): chip.addWidget(w)
        chip.addStretch(); lp.addLayout(chip)
        self.locked_card = LockedCard(True)
        self.locked_card.clicked.connect(self.open_vault)
        lp.addWidget(self.locked_card, 0, Qt.AlignCenter)

        self.view = VaultView()
        self.view.lockRequested.connect(self.lock)
        self.view.addRequested.connect(self.add_files)
        self.view.openRequested.connect(self.open_file)
        self.view.moveRequested.connect(self.move_file)
        self.view.newFolderRequested.connect(self.new_folder)
        self.view.renameFolder.connect(self.rename_folder)
        self.view.deleteFolder.connect(self.delete_folder)
        self.view.settingsRequested.connect(self.open_settings)
        self.view.exportRequested.connect(self.export_file)
        self.view.deleteRequested.connect(self.delete_file)
        self.picker = UserPicker()
        self.picker.chosen.connect(self.select_user); self.picker.addRequested.connect(self.add_user)
        self.picker.restoreRequested.connect(self.restore_backup)
        self._idle = QTimer(self); self._idle.setSingleShot(True); self._idle.timeout.connect(self._auto_lock)
        QApplication.instance().installEventFilter(self)       # any mouse / key activity resets the idle timer
        self.stack.addWidget(self.locked_page); self.stack.addWidget(self.view); self.stack.addWidget(self.picker)
        self._show_picker()

    def open_vault(self) -> None:
        fresh = not self.vault.exists()
        submit = (lambda pw: self.vault.create(pw, f"{self.user['name']}'s Vault")) if fresh else \
                 self._unlock_attempt
        if PasswordDialog(self, fresh, submit).exec() == QDialog.Accepted:
            self._refresh(); self.stack.setCurrentIndex(1); self._arm_autolock()

    def lock(self, quiet: bool = False) -> bool:
        if self._job and self._job.isRunning(): return False
        stuck = self._flush_open()
        if stuck:
            if not quiet: QMessageBox.warning(self, "Files still open", "Close these files in their apps first, then lock again:\n\n• " + "\n• ".join(stuck))
            return False
        self._idle.stop(); self.vault.lock(); self.view.refresh([], [])
        self.locked_card.fresh = not self.vault.exists(); self.locked_card.update()
        self.stack.setCurrentIndex(0)
        return True

    def add_files(self, paths: list[str]) -> None:
        zone = self.view.zone
        if zone.busy: return
        zone.begin_processing()
        delete, folder = self.view.delete_orig.isChecked(), self.view.cur       # files land in the folder you're viewing
        self._job = Job(lambda cb: self.vault.add_files(paths, folder, delete, cb))
        self._job.progress.connect(zone.set_progress)
        self._job.ok.connect(lambda _: zone.flash_success(self._after_add))  # success flash, then update grid
        self._job.fail.connect(lambda m: (zone.reset(), QMessageBox.warning(self, "Vault", m)))
        self._job.start()

    # ---- opening files --------------------------------------------------
    def _refresh(self) -> None:
        self.view.refresh(self.vault.entries, self.vault.folders)

    def _apply_title(self) -> None:
        t = self.vault.title() if self.vault.exists() else f"{self.user['name']}'s Vault"
        self.setWindowTitle(t); self.brand.setText(t.upper()); self.view.title_lbl.setText(t.upper())

    # ---- users ----------------------------------------------------------
    def _show_picker(self) -> None:
        self.setWindowTitle(APP_NAME); self.picker.refresh(self.store); self.stack.setCurrentIndex(2)

    def select_user(self, user: dict) -> None:
        self.user, self.vault = user, Vault(self.store.dir(user["id"]))     # each user has a separate vault folder
        self.locked_card.fresh = not self.vault.exists(); self.locked_card.update()
        self._apply_user(); self._apply_title(); self.stack.setCurrentIndex(0)

    def add_user(self) -> None:
        name, ok = QInputDialog.getText(self, "New user", "Name for the new user:")
        if ok and name.strip(): self.select_user(self.store.add(name.strip()))

    def _apply_user(self) -> None:
        for av in (self.view.avatar, self.chip_av): av.set_user(self.user, self.store)
        self.chip_name.setText(self.user["name"])

    def _delete_user(self, dlg: QDialog) -> None:
        if QMessageBox.question(self, "Delete user", f"Permanently delete “{self.user['name']}” and every file in their vault?\nThis cannot be undone.") != QMessageBox.Yes:
            return
        dlg.accept(); self.vault.wipe_tmp(); self.opened.clear(); self.vault.lock()
        self.store.remove(self.user); self.vault = self.user = None
        self.view.refresh([], []); self._show_picker()

    # ---- auto-lock ------------------------------------------------------
    def _unlock_attempt(self, pw: str):
        try:
            return None if self.vault.unlock(pw) else "Incorrect password."
        except ValueError as e:                              # e.g. damaged index
            return str(e)

    def _arm_autolock(self) -> None:
        mins = (self.user or {}).get("autolock", 5)
        if mins and self.vault and self.vault.key:
            self._idle.start(mins * 60_000)
        else:
            self._idle.stop()

    def _auto_lock(self) -> None:
        if not (self.vault and self.vault.key): return
        if QApplication.activeModalWidget() or not self.lock(quiet=True):
            self._idle.start(60_000)        # busy (dialog, import, or a file still open elsewhere): retry in a minute

    def eventFilter(self, obj, ev) -> bool:
        if ev.type() in (QEvent.MouseMove, QEvent.MouseButtonPress, QEvent.KeyPress, QEvent.Wheel):
            self._arm_autolock()
        return super().eventFilter(obj, ev)

    def changeEvent(self, e) -> None:
        super().changeEvent(e)
        if (e.type() == QEvent.WindowStateChange and self.isMinimized() and self.vault and self.vault.key
                and self.user.get("lock_on_minimize", True) and self.stack.currentIndex() == 1):
            QTimer.singleShot(0, lambda: self.lock(quiet=True))

    # ---- backup / restore -----------------------------------------------
    def export_backup(self) -> None:
        name = f"{self.user['name']}_{time.strftime('%Y%m%d')}.dvbak"
        dest, _ = QFileDialog.getSaveFileName(self, "Save encrypted backup", name, "Daedalus backup (*.dvbak)")
        if not dest: return
        self.view.count.setText("Writing backup…")
        self._job = Job(lambda cb: self.vault.backup(dest, cb))
        self._job.ok.connect(lambda q: (self._refresh(), QMessageBox.information(self, "Backup saved",
                             f"Encrypted backup saved to:\n{q}\n\nIt stays encrypted: you still need your password to open it.")))
        self._job.fail.connect(lambda m: (self._refresh(), QMessageBox.warning(self, "Vault", m)))
        self._job.start()

    def verify_vault(self) -> None:
        self.view.count.setText("Verifying files…")
        self._job = Job(lambda cb: self.vault.verify(cb))
        self._job.ok.connect(self._show_verify)
        self._job.fail.connect(lambda m: (self._refresh(), QMessageBox.warning(self, "Vault", m)))
        self._job.start()

    def _show_verify(self, r: dict) -> None:
        self._refresh()
        bad = r["damaged"] + r["missing"]
        lines = [f"Checked {r['checked']} file{'s' if r['checked'] != 1 else ''}."]
        if not bad: lines.append("Everything is intact.")
        if r["damaged"]: lines.append("Damaged: " + ", ".join(r["damaged"][:10]))
        if r["missing"]: lines.append("Missing: " + ", ".join(r["missing"][:10]))
        if r["orphans"]: lines.append(f"{len(r['orphans'])} unreferenced encrypted file(s), left over from interrupted imports.")
        (QMessageBox.warning if bad else QMessageBox.information)(self, "Vault check", "\n".join(lines))

    def upgrade_files(self) -> None:
        self.view.count.setText("Upgrading files…")
        self._job = Job(lambda cb: self.vault.upgrade_blobs(cb))
        self._job.ok.connect(lambda n: (self._refresh(), QMessageBox.information(self, "Upgrade", f"{n} file(s) upgraded.")))
        self._job.fail.connect(lambda m: (self._refresh(), QMessageBox.warning(self, "Vault", m)))
        self._job.start()

    def restore_backup(self) -> None:
        f, _ = QFileDialog.getOpenFileName(self, "Choose a backup", "", "Daedalus backup (*.dvbak)")
        if not f: return
        name, ok = QInputDialog.getText(self, "Restore backup", "Name for the restored user:", text=Path(f).stem.split("_")[0])
        if not ok or not name.strip(): return
        try:
            u = self.store.restore(f, name.strip())
        except ValueError as e:
            QMessageBox.warning(self, "Restore", str(e)); return
        self.select_user(u)                                  # unlock it with the original password

    def _after_add(self) -> None:
        self._refresh()
        n = len(getattr(self.vault, "skipped", []))
        if n:
            names = "\n• ".join(os.path.basename(x) for x in self.vault.skipped[:8]) + ("\n• …" if n > 8 else "")
            QMessageBox.warning(self, "Some files were skipped",
                                f"{n} file{'s' if n != 1 else ''} couldn't be read (in use or no permission) and were left where they are:\n\n• {names}")

    def _attempt(self, fn, *args) -> bool:
        try:
            fn(*args); return True
        except ValueError as e:
            QMessageBox.warning(self, "Vault", str(e)); return False

    # ---- folders / moving -----------------------------------------------
    def new_folder(self) -> None:
        name, ok = QInputDialog.getText(self, "New folder", "Folder name:")
        if ok and self._attempt(self.vault.add_folder, self.view.cur, name): self._refresh()

    def rename_folder(self, path: str) -> None:
        name, ok = QInputDialog.getText(self, "Rename folder", "New name:", text=path.rpartition("/")[2])
        if ok and self._attempt(self.vault.rename_folder, path, name): self._refresh()

    def delete_folder(self, path: str) -> None:
        if self._attempt(self.vault.delete_folder, path): self._refresh()

    def move_file(self, entry: dict) -> None:
        opts = ["Vault (top level)"] + sorted(self.vault.folders, key=str.lower)
        cur = entry.get("folder", "")
        choice, ok = QInputDialog.getItem(self, "Move file", f"Move “{entry['name']}” to:", opts, opts.index(cur) if cur in opts else 0, False)
        if ok: self.vault.move(entry, "" if choice == opts[0] else choice); self._refresh()

    # ---- settings: vault name, main password, backup password -----------------
    def _new_password(self, title: str, sub: str, fn) -> bool:
        def submit(pw: str):
            try: fn(pw)
            except ValueError as e: return str(e)
        return PasswordDialog(self, True, submit, title, sub, "Save").exec() == QDialog.Accepted

    def open_settings(self) -> None:
        d = QDialog(self); d.setWindowTitle("Settings"); d.setFixedWidth(440)
        lay = QVBoxLayout(d); lay.setContentsMargins(30, 26, 30, 24); lay.setSpacing(10)

        def note(text: str) -> QLabel:
            l = QLabel(text); l.setWordWrap(True); l.setStyleSheet(f"color:{MUTED}; font:9pt '{FONT}';"); return l

        h = QLabel("Settings"); h.setFont(QFont(FONT, 15, QFont.DemiBold)); lay.addWidget(h)
        lay.addWidget(note("Profile"))
        prof = QHBoxLayout(); av = Avatar(72); av.set_user(self.user, self.store); prof.addWidget(av)
        col = QVBoxLayout(); uname = QLineEdit(self.user["name"]); col.addWidget(uname)
        row = QHBoxLayout(); up, rm = QPushButton("Upload avatar…"), QPushButton("Remove"); row.addWidget(up); row.addWidget(rm)
        col.addLayout(row); prof.addLayout(col); lay.addLayout(prof)

        def refresh_profile() -> None:
            av.set_user(self.user, self.store); self._apply_user()

        def rename() -> None:
            if uname.text().strip(): self.store.update(self.user, name=uname.text().strip()); refresh_profile()

        def pick() -> None:
            f, _ = QFileDialog.getOpenFileName(d, "Choose an avatar", "", "Images (*.png *.jpg *.jpeg *.bmp *.webp *.gif)")
            if f and self._attempt(self.store.set_avatar, self.user, f): refresh_profile()

        uname.editingFinished.connect(rename); up.clicked.connect(pick)
        rm.clicked.connect(lambda: (self.store.clear_avatar(self.user), refresh_profile()))
        sw = QHBoxLayout()                                           # profile colour (avatar ring)
        for c in PALETTE:
            b = QPushButton(); b.setFixedSize(26, 26); b.setCursor(Qt.PointingHandCursor)
            b.setStyleSheet(f"background:{c}; border:2px solid {LINE}; border-radius:13px; padding:0;")
            b.clicked.connect(lambda _=False, c=c: (self.store.update(self.user, color=c), refresh_profile())); sw.addWidget(b)
        sw.addStretch(); lay.addLayout(sw); lay.addSpacing(8)
        lay.addWidget(note("Vault name (shown on the lock screen and title bar)"))
        name = QLineEdit(self.vault.title()); lay.addWidget(name)
        b = QPushButton("Save name"); lay.addWidget(b)
        b.clicked.connect(lambda: (self.vault.set_title(name.text()), self._apply_title(), d.accept()))
        lay.addSpacing(8); lay.addWidget(note("Main password"))
        b = QPushButton("Change main password"); lay.addWidget(b)
        b.clicked.connect(lambda: self._new_password("Change main password", "Choose a new main password.", self.vault.change_password) and d.accept())
        lay.addSpacing(8)
        has = self.vault.has_backup()
        lay.addWidget(note("Backup password: " + ("set" if has else "not set") + ". A second password that also opens the vault. "
                           "If you forget your main password, unlock with the backup, then change the main one here."))
        b = QPushButton("Change backup password" if has else "Set backup password"); lay.addWidget(b)
        b.clicked.connect(lambda: self._new_password("Backup password", "Choose a backup password that is different from your main one.", self.vault.set_backup) and d.accept())
        if has:
            r = QPushButton("Remove backup password"); lay.addWidget(r)
            r.clicked.connect(lambda: (self.vault.remove_backup(), d.accept()))
        lay.addSpacing(8); lay.addWidget(note("Security"))
        mins = [0, 1, 5, 15, 30]
        ac = QComboBox(); ac.addItems(["Auto-lock: never"] + [f"Auto-lock after {m} min idle" for m in mins[1:]])
        cur = self.user.get("autolock", 5); ac.setCurrentIndex(mins.index(cur) if cur in mins else 2)
        ac.currentIndexChanged.connect(lambda i: (self.store.update(self.user, autolock=mins[i]), self._arm_autolock()))
        lay.addWidget(ac)
        lm = QCheckBox("Lock when the window is minimized"); lm.setChecked(self.user.get("lock_on_minimize", True))
        lm.toggled.connect(lambda v: self.store.update(self.user, lock_on_minimize=v)); lay.addWidget(lm)
        bk = QPushButton("Export encrypted backup…"); lay.addWidget(bk)
        bk.clicked.connect(lambda: (d.accept(), self.export_backup()))
        vf = QPushButton("Verify vault integrity"); lay.addWidget(vf)
        vf.clicked.connect(lambda: (d.accept(), self.verify_vault()))
        legacy = sum(e.get("fmt") != 2 for e in self.vault.entries)
        if legacy:
            up2 = QPushButton(f"Upgrade {legacy} older file{'s' if legacy != 1 else ''} to the newer format…"); lay.addWidget(up2)
            up2.clicked.connect(lambda: (d.accept(), self.upgrade_files()))
        lay.addSpacing(10)
        dz = QPushButton("Delete this user and their vault…"); dz.setStyleSheet(f"color:{ERROR};"); lay.addWidget(dz)
        dz.clicked.connect(lambda: self._delete_user(d))
        d.exec()

    def open_file(self, entry: dict) -> None:
        """Images -> built-in in-memory viewer. Everything else -> decrypt to temp + open in default app."""
        if self._job and self._job.isRunning(): return
        if entry["mime"].startswith("image/") and entry["size"] < 150 * 1024 * 1024:
            self._job = Job(lambda cb: self.vault.read_bytes(entry, cb))
            self._job.ok.connect(lambda data: self._show_image(entry, data))
            self._job.fail.connect(lambda m: QMessageBox.warning(self, "Vault", m))
            self._job.start()
        else:
            self._open_external(entry)

    def _show_image(self, entry: dict, data: bytes) -> None:
        dlg = ImageViewer(self, entry["name"], data)
        if dlg.valid(): dlg.exec()
        else: self._open_external(entry)        # format Qt can't decode -> default app

    def _open_external(self, entry: dict) -> None:
        o = self.opened.get(entry["id"])
        if o and Path(o["path"]).exists():       # already decrypted: reopen without overwriting edits
            return self._launch(o["path"])
        self.view.count.setText(f"Decrypting {entry['name']}…")
        self._job = Job(lambda cb: self.vault.open_temp(entry, cb))

        def done(path: str) -> None:
            st = os.stat(path)
            self.opened[entry["id"]] = {"entry": entry, "path": path, "stamp": (st.st_mtime_ns, st.st_size)}
            self._refresh()
            self._launch(path)

        self._job.ok.connect(done)
        self._job.fail.connect(lambda m: (self._refresh(), QMessageBox.warning(self, "Vault", m)))
        self._job.start()

    def _launch(self, path: str) -> None:
        try:
            os.startfile(path)                   # Windows default app: Excel, Word, PDF reader, video player…
        except OSError as e:
            QMessageBox.warning(self, "Open", f"No app is set up to open this file type.\n{e}")

    def _flush_open(self) -> list[str]:
        """Save edited temp copies back into the vault and wipe them. Returns names still held open by an app."""
        stuck: list[str] = []
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            for eid, o in list(self.opened.items()):
                p = Path(o["path"])
                try:
                    if p.exists():
                        if not o.get("wiped"):
                            st = p.stat()
                            if (st.st_mtime_ns, st.st_size) != o["stamp"]:     # edited -> save back
                                self.vault.replace_blob(o["entry"], str(p))
                            Vault.wipe_file(p)                                  # fails if the app still locks it
                            o["wiped"] = True
                        p.unlink()
                    shutil.rmtree(p.parent, ignore_errors=True)
                    del self.opened[eid]
                except OSError:
                    stuck.append(o["entry"]["name"])
        finally:
            QApplication.restoreOverrideCursor()
        return stuck

    def export_file(self, entry: dict) -> None:
        dest = QFileDialog.getExistingDirectory(self, "Export to folder")
        if not dest: return
        self._job = Job(lambda cb: self.vault.export(entry, dest, cb))
        self._job.ok.connect(lambda p: QMessageBox.information(self, "Exported", f"Decrypted copy saved to:\n{p}"))
        self._job.fail.connect(lambda m: QMessageBox.warning(self, "Vault", m))
        self._job.start()

    def delete_file(self, entry: dict) -> None:
        if QMessageBox.question(self, "Delete", f"Permanently delete “{entry['name']}” from the vault?") == QMessageBox.Yes:
            o = self.opened.pop(entry["id"], None)
            if o: shutil.rmtree(Path(o["path"]).parent, ignore_errors=True)
            self.vault.remove(entry); self._refresh()

    def closeEvent(self, e) -> None:
        if self._job and self._job.isRunning(): self._job.wait()
        stuck = self._flush_open()
        if stuck and QMessageBox.question(self, "Quit", "These files are still open:\n• " + "\n• ".join(stuck) +
                "\n\nQuit anyway? Unsaved edits are lost; temporary copies are wiped on next launch.") != QMessageBox.Yes:
            e.ignore(); return
        if self.vault: self.vault.lock()
        super().closeEvent(e)


if __name__ == "__main__":
    app = QApplication(sys.argv)
    app.setApplicationName(APP_NAME)
    app.setWindowIcon(QIcon(logo_pixmap()))
    try:  # own taskbar identity so Windows shows our icon instead of Python's
        import ctypes
        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID("Daedalus.Vault.1")
    except Exception:
        pass
    app.setStyleSheet(STYLE)
    win = MainWindow(); win.show()
    sys.exit(app.exec())